-- Roadshow Driver: Phase 2 driver experience
alter table public.profiles add column if not exists phone text;
create table if not exists public.feedback (id uuid primary key default gen_random_uuid(),submitted_by uuid not null references public.profiles(id) on delete cascade,category text not null check(category in ('app','setup','teardown')),message text not null check(length(message) between 1 and 5000),status text not null default 'new' check(status in ('new','reviewed','closed')),created_at timestamptz not null default now());
alter table public.feedback enable row level security;
create policy "drivers submit feedback" on public.feedback for insert to authenticated with check(submitted_by=auth.uid());
create policy "drivers read own feedback" on public.feedback for select to authenticated using(submitted_by=auth.uid() or public.is_admin());
create policy "admins manage feedback" on public.feedback for all using(public.is_admin()) with check(public.is_admin());
revoke update on public.profiles from authenticated;
grant update(full_name,avatar_url,phone,updated_at) on public.profiles to authenticated;
create or replace function public.sign_my_contract(contract_id uuid, signer_name text) returns void language plpgsql security definer set search_path=public as $$ begin if length(trim(signer_name)) < 2 then raise exception 'A full legal name is required'; end if; update public.contracts set signature_name=trim(signer_name),signed_at=now(),status='signed',updated_at=now() where id=contract_id and driver_id=auth.uid() and signed_at is null; if not found then raise exception 'Contract is unavailable or already signed'; end if; end $$;
grant execute on function public.sign_my_contract(uuid,text) to authenticated;
create policy "drivers sign assigned contracts" on public.contracts for update to authenticated using(driver_id=auth.uid()) with check(driver_id=auth.uid());
create or replace function public.guard_driver_contract_update() returns trigger language plpgsql security definer set search_path=public as $$ begin if auth.uid()=old.driver_id and not public.is_admin() then if new.show_id is distinct from old.show_id or new.driver_id is distinct from old.driver_id or new.kind is distinct from old.kind or new.contract_pay is distinct from old.contract_pay or new.bonus_pay is distinct from old.bonus_pay or new.document_path is distinct from old.document_path or new.submitted_at is distinct from old.submitted_at or new.reviewed_at is distinct from old.reviewed_at or new.reviewed_by is distinct from old.reviewed_by or new.admin_note is distinct from old.admin_note or new.status not in ('signed','in_progress') then raise exception 'Drivers may only sign or begin their assigned contract'; end if; end if; return new; end $$;
create trigger guard_driver_contract_update before update on public.contracts for each row execute function public.guard_driver_contract_update();
revoke insert,update on public.checklist_responses from authenticated;
grant select on public.checklist_responses to authenticated;
grant insert(contract_checklist_id,item_id,completed,note,completed_at) on public.checklist_responses to authenticated;
grant update(completed,note,completed_at) on public.checklist_responses to authenticated;
create or replace function public.guard_driver_availability() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() and (new.driver_id<>auth.uid() or new.status not in ('available','unavailable')) then raise exception 'Drivers may only set their own availability'; end if; return new; end $$;
create trigger guard_driver_availability before insert or update on public.availability for each row execute function public.guard_driver_availability();
create or replace function public.submit_my_checklist(target_contract_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if exists(select 1 from public.contract_checklists cc join public.checklist_items i on i.section_id in (select id from public.checklist_sections where template_id=cc.template_id) left join public.checklist_responses r on r.contract_checklist_id=cc.id and r.item_id=i.id where cc.contract_id=target_contract_id and i.required and coalesce(r.completed,false)=false) then raise exception 'Complete every required checklist item first'; end if; update public.contracts set status='submitted',submitted_at=now(),updated_at=now() where id=target_contract_id and driver_id=auth.uid() and signed_at is not null; if not found then raise exception 'Sign the contract before submitting'; end if; end $$;
grant execute on function public.submit_my_checklist(uuid) to authenticated;
create policy "drivers upload own roadshow photos" on storage.objects for insert to authenticated with check(bucket_id='roadshow-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "drivers read own roadshow photos" on storage.objects for select to authenticated using(bucket_id='roadshow-photos' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
create policy "drivers delete own roadshow photos" on storage.objects for delete to authenticated using(bucket_id='roadshow-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "authenticated read resource files" on storage.objects for select to authenticated using(bucket_id='resources');
